diff --git a/bitset.go b/bitset.go
index 46d05b9..102a69f 100644
--- a/bitset.go
+++ b/bitset.go
@@ -353,7 +353,7 @@ func (b *BitSet) FlipRange(start, end uint) *BitSet {
 	//
 	// is end at word boundary?
 	if idx := wordsIndex(-end); idx != 0 {
-		b.set[endWord] ^= ^uint64(0) >> wordsIndex(idx)
+		b.set[endWord] ^= ^uint64(0) >> (64 - idx)
 	}

 	return b

